K = "K"
P2raw = [
("행복", 3, "동양 사상가의 행복관에 대한 연결로 옳은 것은?", ["노자 – 인위적인 것을 버리고 자연의 순리에 따르는 무위자연의 삶", "공자 – 모든 욕망과 집착에서 벗어난 해탈", "석가모니 – 인(仁)을 실천하는 군자의 삶", "맹자 – 소요유를 통한 절대적 자유", "장자 – 예(禮)를 통한 사회 질서 회복"], "공자=인·예, 석가모니=해탈·열반, 장자=소요유, 맹자=성선설·인의."),
("행복", 3, "행복의 조건 중 '민주주의의 실현'과 관련된 설명으로 가장 적절한 것은?", ["시민이 정치 과정에 참여하고 기본권이 보장될 때 삶의 만족도가 높아진다.", "경제 성장률이 높으면 항상 행복 지수가 높다.", "개인의 도덕성은 행복과 무관하다.", "자연환경은 행복의 조건이 아니다.", "소득이 일정 수준을 넘으면 행복이 무한히 증가한다."], "질 높은 정주 환경, 경제적 안정, 민주주의 실현, 도덕적 실천과 성찰이 행복의 조건."),
("자연환경", 3, "건조 기후 지역의 전통 가옥 특징으로 옳은 것만을 고른 것은?\nㄱ. 흙벽돌로 벽을 두껍게 만든다.\nㄴ. 창문을 작게 만든다.\nㄷ. 지붕의 경사를 급하게 만든다.", K, "ㄱ, ㄴ", "강수가 적어 지붕은 평평(ㄷ은 열대·다우 지역). 큰 일교차와 강한 햇볕 대비."),
("자연환경", 3, "툰드라 기후 지역 주민의 생활 모습으로 가장 적절한 것은?", ["순록을 유목하고 가옥을 지면에서 띄워 짓는다.", "벼농사를 일 년에 두세 번 짓는다.", "올리브와 포도를 재배한다.", "오아시스 주변에서 대추야자를 재배한다.", "고상 가옥에서 생활하며 이동식 화전 농업을 한다."], "영구 동토층이 녹아 가옥이 기우는 것을 막기 위해 고상식 가옥. 순록 유목."),
("자연환경", 3, "지중해성 기후의 특징과 농업으로 옳은 것은?", ["여름은 고온 건조, 겨울은 온난 습윤하여 올리브·포도 등 수목 농업이 발달한다.", "연중 고온 다습하여 플랜테이션이 발달한다.", "여름에 비가 많고 겨울이 건조하여 벼농사가 발달한다.", "연중 강수가 적어 유목이 발달한다.", "연중 기온이 낮아 농업이 거의 불가능하다."], "여름 아열대 고압대의 영향으로 건조 → 건조에 강한 수목 농업."),
("자연환경", 4, "자연재해와 대책의 연결로 옳지 않은 것은?", ["지진 – 하천 제방을 높게 쌓는다.", "홍수 – 유수지·저류지를 만든다.", "가뭄 – 저수지·댐을 건설한다.", "태풍 – 방파제를 쌓고 예보 체계를 강화한다.", "폭설 – 제설 장비를 확보하고 지붕 경사를 급하게 한다."], "지진 대책은 내진 설계, 대피 훈련. 제방은 홍수 대책."),
("자연환경", 3, "환경 문제와 관련 국제 협약의 연결로 옳은 것은?", ["오존층 파괴 – 몬트리올 의정서", "지구 온난화 – 람사르 협약", "사막화 – 바젤 협약", "습지 보호 – 사막화 방지 협약", "유해 폐기물 이동 – 파리 협정"], "온난화=기후 변화 협약·교토 의정서·파리 협정, 습지=람사르, 유해 폐기물=바젤."),
("자연환경", 3, "산성비의 원인 물질로 가장 적절한 것은?", ["황산화물과 질소 산화물", "프레온 가스", "이산화 탄소와 메테인", "미세 플라스틱", "중금속"], "SOx, NOx가 빗물에 녹아 산성비. 프레온=오존층 파괴."),
("자연환경", 4, "생태 중심주의 관점에서 제시할 주장으로 가장 적절한 것은?", ["인간은 생태계의 구성원으로서 생태계 전체의 균형과 안정을 고려해야 한다.", "자연은 인간의 필요를 위해 존재하므로 개발이 우선이다.", "고통을 느끼는 동물만 도덕적 고려 대상이다.", "개별 생명체만 내재적 가치를 지니며 생태계는 그렇지 않다.", "자연과 인간은 엄격히 분리된다."], "레오폴드의 대지 윤리 등 생태 중심주의는 전일론적 관점(생태계 전체)."),
("생활공간", 3, "산업화·도시화에 따른 변화로 옳지 않은 것은?", ["촌락의 인구 증가와 청장년층 비율 증가", "도시의 주택 부족과 교통 혼잡", "직업의 분화와 전문화", "이촌 향도 현상", "도시 내부의 지역 분화"], "촌락은 인구 감소·고령화가 나타난다."),
("생활공간", 3, "대도시 도심의 특징으로 옳은 것은?", ["지가와 접근성이 높아 상업·업무 기능이 집중되고 인구 공동화 현상이 나타난다.", "주거 기능이 가장 발달한다.", "주간 인구보다 상주인구가 훨씬 많다.", "대규모 공장이 집중 분포한다.", "녹지 비율이 가장 높다."], "도심: 중심 업무 지구, 높은 지가, 인구 공동화(주간 인구 많음)."),
("생활공간", 3, "지리 정보 시스템(GIS)을 활용한 입지 선정의 예로 가장 적절한 것은?", ["여러 공간 정보를 중첩 분석하여 최적의 장소를 찾는다.", "설문 조사만으로 장소를 결정한다.", "가장 넓은 땅을 무조건 선택한다.", "지도 없이 현장 답사만 한다.", "지역 주민의 의견을 배제한다."], "GIS는 여러 지리 정보 레이어를 중첩(overlay)해 분석."),
("생활공간", 4, "고속 철도 개통 이후 나타날 수 있는 변화로 옳은 것만을 고른 것은?\nㄱ. 대도시와 중소 도시 사이의 시간 거리가 줄어든다.\nㄴ. 중소 도시의 의료·쇼핑 수요가 대도시로 흡수될 수 있다.\nㄷ. 기존 철도역 주변 상권은 반드시 성장한다.", K, "ㄱ, ㄴ", "빨대 효과(ㄴ). 고속철 역과 거리가 먼 기존 상권은 쇠퇴할 수도 있다."),
("인권", 3, "인권의 역사적 발달 과정에 대한 설명으로 옳은 것은?", ["시민 혁명 이후 자유권이, 산업 혁명 이후 노동자 보호와 관련된 사회권이 강조되었다.", "사회권은 시민 혁명 이전에 가장 먼저 등장하였다.", "참정권은 처음부터 모든 시민에게 보장되었다.", "연대권은 18세기에 등장하였다.", "세계 인권 선언은 1차 세계 대전 이전에 채택되었다."], "자유권(17~18세기 시민 혁명) → 참정권 확대(19~20세기) → 사회권(바이마르 헌법, 1919) → 연대권(20세기 후반). 세계 인권 선언 1948."),
("인권", 3, "다음 중 청구권에 해당하는 것은?", ["국가 배상 청구권", "교육받을 권리", "공무 담임권", "거주·이전의 자유", "환경권"], "청구권: 청원권, 재판 청구권, 국가 배상 청구권, 형사 보상 청구권 등. 교육·환경권=사회권, 공무 담임권=참정권."),
("인권", 3, "주민 참여 제도 중 주민이 지방 자치 단체장을 임기 중 해임할 수 있는 제도는?", ["주민 소환제", "주민 투표제", "주민 발안제", "주민 참여 예산제", "주민 소송제"], "주민 소환제=선출직 공무원 해임 투표."),
("인권", 4, "국가 인권 위원회에 대한 설명으로 옳은 것은?", ["인권 침해나 차별 행위에 대해 조사하고 시정을 권고할 수 있다.", "법률의 위헌 여부를 최종 결정한다.", "형사 재판을 담당한다.", "국회의원 선거를 관리한다.", "권고는 법적 구속력을 갖는다."], "국가 인권 위원회의 권고는 법적 구속력이 없으나 인권 보호에 기여. 위헌 결정=헌법재판소."),
("인권", 3, "근로자의 권리에 대한 설명으로 옳은 것은?", ["노동 3권은 단결권, 단체 교섭권, 단체 행동권이다.", "근로 기준법은 사용자와 근로자가 합의하면 무시할 수 있다.", "청소년은 근로 계약을 맺을 수 없다.", "최저 임금은 사용자 마음대로 정한다.", "부당 해고는 구제받을 방법이 없다."], "근로 기준법은 최저 기준(합의로 그 이하 불가). 부당 해고는 노동 위원회에 구제 신청 가능."),
("인권", 3, "사회적 소수자에 대한 차별 해소 방안으로 '적극적 우대 조치'의 예는?", ["장애인 의무 고용 제도", "모든 지원자에게 같은 시험 실시", "소수자 관련 통계 폐지", "차별 금지 조항 삭제", "소수자의 정치 참여 제한"], "적극적 우대 조치(affirmative action): 구조적 불리함을 보정하는 할당제 등."),
("시장경제", 3, "다음 중 공공재의 특징으로 옳은 것은?", ["비경합성과 비배제성 때문에 무임승차 문제가 발생한다.", "가격을 내지 않은 사람을 쉽게 배제할 수 있다.", "시장에서 사회적 최적 수준보다 과다 공급된다.", "한 사람의 소비가 다른 사람의 소비를 감소시킨다.", "정부는 공공재를 공급하지 않는다."], "공공재는 시장에서 과소 공급되므로 정부가 공급."),
("시장경제", 3, "외부 효과에 대한 설명으로 옳은 것은?", ["양봉업자 덕분에 과수원 수확이 늘어난 것은 외부 경제이다.", "공장 폐수로 인한 피해는 외부 경제이다.", "외부 불경제가 발생하면 사회적 최적 수준보다 과소 생산된다.", "외부 경제가 발생하면 사회적 최적 수준보다 과다 생산된다.", "외부 효과는 시장 가격에 정확히 반영된다."], "외부 불경제 → 과다 생산, 외부 경제 → 과소 생산. 가격에 반영되지 않는 것이 외부 효과."),
("시장경제", 3, "금융 자산의 특징에 대한 설명으로 옳은 것은?", ["주식은 예금보다 수익성은 높을 수 있으나 안전성은 낮다.", "예금은 수익성과 안전성이 모두 가장 높다.", "채권은 배당금을 받을 수 있다.", "주식은 원금이 보장된다.", "유동성은 부동산이 현금보다 높다."], "예금: 안전성↑ 수익성↓, 주식: 수익성↑ 안전성↓(배당·시세차익), 채권: 이자. 현금의 유동성이 가장 높다."),
("시장경제", 3, "자유 무역 확대의 영향으로 적절하지 않은 것은?", ["모든 국내 산업이 이익을 얻는다.", "소비자의 상품 선택 폭이 넓어진다.", "비교 우위 산업은 성장 기회를 얻는다.", "경쟁력이 약한 산업은 어려움을 겪을 수 있다.", "국가 간 상호 의존성이 커진다."], "경쟁력 약한 산업은 피해를 볼 수 있어 이익이 고르게 돌아가지 않는다."),
("시장경제", 4, "윤리적 소비의 사례로 가장 적절한 것은?", ["노동 착취 없이 생산된 공정 무역 커피를 구매한다.", "가장 싼 상품만 구매한다.", "유행에 따라 자주 옷을 교체한다.", "광고 모델을 보고 제품을 고른다.", "환경 정보를 무시하고 편리함만 고려한다."], "윤리적 소비: 인권·환경·동물 복지 등을 고려한 소비(공정 무역, 로컬 푸드 등)."),
("시장경제", 3, "기업가 정신과 기업의 사회적 책임에 대한 설명으로 옳은 것은?", ["기업은 이윤 추구와 함께 법 준수, 환경 보호, 사회 공헌 등의 책임을 진다.", "기업의 유일한 책임은 이윤 극대화이므로 환경은 고려하지 않는다.", "혁신은 기업가 정신과 무관하다.", "노동자의 권리 보장은 기업의 책임이 아니다.", "기업은 소비자 정보를 공개할 필요가 없다."], "슘페터의 혁신, 기업의 경제적·법적·윤리적·자선적 책임."),
("정의와 사회", 3, "분배 정의의 기준 중 '업적'에 따른 분배의 장점은?", ["생산성 향상의 동기를 부여한다.", "사회적 약자를 우선 보호한다.", "업적을 평가하기 매우 쉽다.", "모든 사람에게 같은 몫을 준다.", "경쟁을 완전히 없앤다."], "업적: 동기 부여 장점, 평가 기준의 어려움·약자 배려 부족 단점."),
("정의와 사회", 3, "분배 기준 중 '필요'에 따른 분배의 한계로 옳은 것은?", ["한정된 자원으로 모든 필요를 충족시키기 어렵고 성취 동기를 떨어뜨릴 수 있다.", "약자에게 불리하다.", "생산성 향상 동기가 지나치게 크다.", "능력 있는 사람만 혜택을 본다.", "모두에게 똑같이 분배해야 한다."], "필요: 약자 보호 장점, 자원 한계·동기 저하 단점."),
("정의와 사회", 3, "공리주의 관점의 정의관으로 옳은 것은?", ["사회 전체의 행복(효용)을 최대화하는 것이 정의이다.", "개인의 권리는 어떤 경우에도 공리에 우선한다.", "무지의 베일 속에서 합의된 원칙이 정의이다.", "공동체의 전통과 미덕이 정의의 기준이다.", "정당한 소유 권리가 정의의 기준이다."], "벤담·밀: 최대 다수의 최대 행복. 소수 희생 가능성이 비판점."),
("정의와 사회", 4, "자유주의와 공동체주의 정의관을 비교한 것으로 옳은 것은?", ["공동체주의는 공동선과 연대 의식을 강조하며 개인을 공동체 속 존재로 본다.", "자유주의는 공동선을 개인의 권리보다 우선시한다.", "공동체주의는 개인을 공동체와 무관한 독립적 자아로 본다.", "자유주의는 국가가 특정한 좋은 삶을 강요해야 한다고 본다.", "두 입장 모두 개인의 자유를 부정한다."], "자유주의=개인 권리·자유 우선, 국가 중립. 공동체주의(샌델, 매킨타이어)=연고적 자아, 공동선."),
("정의와 사회", 3, "공간 불평등 완화 정책의 사례로 가장 적절한 것은?", ["공공 기관을 지방으로 이전하고 혁신 도시를 조성한다.", "수도권에 모든 대학을 새로 짓는다.", "낙후 지역 교통망 투자를 중단한다.", "대도시에만 의료 시설을 확충한다.", "지역 간 세금 차등을 확대한다."], "지역 균형 발전: 공공 기관 지방 이전, 혁신 도시, 기업 도시 등."),
("정의와 사회", 3, "사회 보장 제도 중 공공 부조에 해당하는 것은?", ["국민 기초 생활 보장 제도", "국민연금", "건강 보험", "고용 보험", "산업 재해 보상 보험"], "공공 부조: 국가가 전액 부담, 생활 능력 없는 사람 대상. 국민연금·보험류는 사회 보험."),
("문화와 다양성", 3, "문화 변동의 요인 중 '간접 전파'의 사례는?", ["인터넷을 통해 외국 음식 조리법이 확산되었다.", "이민자가 들여온 음식이 지역에 퍼졌다.", "새로운 기술이 발명되었다.", "외국 문화를 접하고 아이디어를 얻어 새 문화를 만들었다.", "기존 문화 요소를 결합해 새 문화를 발견하였다."], "직접 전파(사람 이동), 간접 전파(매체), 자극 전파(아이디어만 얻어 창조). 발명·발견은 내재적 요인."),
("문화와 다양성", 3, "자문화 중심주의의 문제점으로 가장 적절한 것은?", ["다른 문화를 열등하게 여겨 국제적 고립이나 갈등을 초래할 수 있다.", "자기 문화의 정체성을 상실하게 한다.", "보편 윤리를 무시한 관습까지 인정한다.", "문화 간 우열을 인정하지 않는다.", "다양성이 지나치게 증가한다."], "② 문화 사대주의, ③ 극단적 문화 상대주의의 문제."),
("문화와 다양성", 3, "다문화 정책 중 '샐러드 볼' 이론의 관점으로 옳은 것은?", ["여러 문화가 고유성을 유지하며 조화롭게 공존해야 한다.", "이주민 문화는 주류 문화에 녹아들어야 한다.", "주류 문화 중심으로 하나의 문화로 통합해야 한다.", "이주민의 문화는 배제해야 한다.", "문화 간 교류를 차단해야 한다."], "용광로(동화) vs 샐러드 볼·국수 대접(다양성 공존, 주류 문화 중심 공존)."),
("문화와 다양성", 4, "다음 중 '보편 윤리'에 근거해 비판받을 수 있는 문화는?", ["노동력 착취가 일상화된 아동 노동 관습", "손으로 음식을 먹는 문화", "명절에 조상에게 차례를 지내는 풍습", "돼지고기를 먹지 않는 식문화", "인사할 때 허리를 굽히는 예절"], "인간 존엄성·생명 존중을 해치는 관습은 문화 상대주의로도 정당화할 수 없다."),
("세계화와 평화", 3, "세계 도시에 대한 설명으로 옳은 것은?", ["다국적 기업 본사와 국제 금융 기능이 집중되어 세계 경제의 중심 역할을 한다.", "인구가 많은 도시는 모두 세계 도시이다.", "주로 1차 산업이 발달한 도시이다.", "국제기구 본부는 세계 도시에 입지하지 않는다.", "세계 도시 간 교류는 줄어드는 추세이다."], "뉴욕·런던·도쿄 등 최상위 세계 도시는 금융·본사·생산자 서비스 집중."),
("세계화와 평화", 3, "다국적 기업의 공간적 분업에 대한 설명으로 옳은 것은?", ["본사는 자본·정보가 풍부한 대도시에, 생산 공장은 저임금 지역이나 시장 근처에 입지한다.", "본사는 임금이 가장 낮은 곳에 입지한다.", "연구소는 원료 산지에만 입지한다.", "생산 공장은 반드시 본국에만 둔다.", "기능별 입지 차이는 없다."], "본사(관리), 연구소(고급 인력), 생산 공장(저임금·시장·무역 장벽 회피)."),
("세계화와 평화", 3, "세계화의 부정적 영향으로 보기 어려운 것은?", ["다양한 문화의 교류로 상품 선택의 폭이 넓어진다.", "국가 간 빈부 격차가 심화될 수 있다.", "문화의 획일화가 나타날 수 있다.", "한 나라의 경제 위기가 다른 나라로 쉽게 확산된다.", "선진국 중심의 질서가 강화될 수 있다."], "①은 긍정적 영향."),
("세계화와 평화", 4, "국제 사회를 보는 관점 중 '자유주의'의 입장으로 옳은 것은?", ["국제기구와 국제법을 통한 협력으로 평화를 유지할 수 있다.", "국가는 자국의 이익과 힘을 최우선으로 추구한다.", "세력 균형을 통해서만 평화가 유지된다.", "국제기구는 강대국의 도구에 불과하다.", "국가 간 협력은 불가능하다."], "현실주의=힘·국익·세력 균형, 자유주의=이성·국제기구·법·여론을 통한 협력."),
("세계화와 평화", 3, "남북통일의 필요성 중 '경제적 측면'에 해당하는 것은?", ["분단 비용을 줄이고 남한의 자본·기술과 북한의 자원·노동력을 결합할 수 있다.", "이산가족의 고통을 해소할 수 있다.", "민족 동질성을 회복할 수 있다.", "동북아 평화에 기여할 수 있다.", "인권 문제를 개선할 수 있다."], "②③⑤ 인도적·민족적, ④ 국제적 측면."),
("세계화와 평화", 3, "동아시아 역사 갈등의 사례로 옳은 것은?", ["일부 국가의 역사 교과서 왜곡과 일본군 위안부 문제", "카슈미르 분쟁", "쿠릴 열도 분쟁만 해당", "팔레스타인 분쟁", "북아일랜드 분쟁"], "동아시아: 역사 교과서 왜곡, 동북공정, 위안부 문제, 야스쿠니 신사 참배 등."),
("미래와 지속가능성", 3, "석유 자원에 대한 설명으로 옳은 것은?", ["편재성이 커서 국제적 이동량이 많고 서남아시아 등에 매장량이 많다.", "고르게 분포하여 국제 이동이 거의 없다.", "주로 제철 공업 원료로 쓰인다.", "산업 혁명기의 주요 에너지원이었다.", "재생 가능한 자원이다."], "산업 혁명기 주 에너지=석탄. 석유는 수송·화학 원료, 편재성 큼."),
("미래와 지속가능성", 3, "지속 가능한 발전에 대한 설명으로 옳은 것은?", ["미래 세대의 필요를 충족시킬 능력을 해치지 않으면서 현세대의 필요를 충족하는 발전이다.", "환경 보전을 위해 모든 개발을 중단하는 것이다.", "경제 성장만을 최우선으로 하는 발전이다.", "선진국만 책임지는 개념이다.", "현세대의 이익을 최우선한다."], "브룬틀란 보고서(1987) 정의. 환경·경제·사회의 조화."),
("미래와 지속가능성", 4, "개발 도상국과 선진국의 인구 문제를 비교한 것으로 옳은 것은?", ["개발 도상국은 급격한 인구 증가와 도시 과밀, 선진국은 저출산·고령화가 주된 문제이다.", "선진국은 출생률이 매우 높다.", "개발 도상국은 노년층 비율이 가장 높다.", "두 집단 모두 인구가 급감하고 있다.", "선진국은 이촌 향도가 가장 활발하다."], "개도국: 높은 출생률, 도시 과밀. 선진국: 저출산·고령화, 노동력 부족."),
("미래와 지속가능성", 3, "탄소 중립을 실현하기 위한 노력으로 가장 거리가 먼 것은?", ["석탄 화력 발전 비중을 늘린다.", "신재생 에너지 비중을 높인다.", "숲을 조성하여 탄소 흡수량을 늘린다.", "전기차 보급을 확대한다.", "건물의 에너지 효율을 높인다."], "탄소 중립=배출량과 흡수량이 같아 순배출 0. 석탄 발전 확대는 역행."),
("한국사", 3, "고구려 광개토 대왕의 업적으로 옳은 것은?", ["신라에 침입한 왜를 격퇴하였다.", "평양으로 천도하였다.", "태학을 설립하였다.", "불교를 처음 공인하였다.", "율령을 반포하였다."], "광개토 대왕: 영락 연호, 요동 확보, 신라 구원(왜 격퇴). 평양 천도=장수왕, 태학·불교·율령=소수림왕."),
("한국사", 3, "백제 근초고왕의 업적으로 옳은 것은?", ["마한을 정복하고 고국원왕을 전사시켰다.", "사비로 천도하였다.", "22담로를 설치하였다.", "신라와 동맹을 처음 맺었다.", "관산성 전투에서 전사하였다."], "사비 천도=성왕, 22담로=무령왕, 관산성 전사=성왕."),
("한국사", 4, "신라 진흥왕 대의 사실로 옳은 것만을 고른 것은?\nㄱ. 화랑도를 국가적 조직으로 개편하였다.\nㄴ. 한강 유역을 차지하였다.\nㄷ. 금관가야를 병합하였다.", K, "ㄱ, ㄴ", "금관가야 병합=법흥왕. 진흥왕은 대가야 정복, 한강 유역 확보, 순수비 건립."),
("한국사", 3, "고려 성종의 정책으로 옳은 것은?", ["최승로의 시무 28조를 수용하여 12목에 지방관을 파견하였다.", "노비안검법을 실시하였다.", "훈요 10조를 남겼다.", "쌍성총관부를 공격하였다.", "전시과를 처음 제정하였다."], "노비안검법=광종, 훈요=태조, 쌍성총관부 수복=공민왕, 시정 전시과=경종."),
("한국사", 3, "고려 공민왕의 개혁으로 옳지 않은 것은?", ["과거제를 처음 실시하였다.", "정동행성 이문소를 폐지하였다.", "쌍성총관부를 무력으로 되찾았다.", "전민변정도감을 설치하였다.", "몽골풍을 금지하였다."], "과거제 실시=광종."),
("한국사", 4, "다음 사건을 시기 순으로 나열한 것은?\n(가) 귀주 대첩  (나) 무신 정변  (다) 삼별초 항쟁  (라) 서희의 외교 담판", ["(라)-(가)-(나)-(다)", "(가)-(라)-(나)-(다)", "(라)-(나)-(가)-(다)", "(가)-(나)-(라)-(다)", "(라)-(가)-(다)-(나)"], "서희 담판(993) → 귀주 대첩(1019) → 무신 정변(1170) → 삼별초 항쟁(1270~1273)."),
("한국사", 3, "조선 태종의 정책으로 옳은 것은?", ["호패법을 실시하고 6조 직계제를 시행하였다.", "경국대전을 반포하였다.", "집현전을 설치하였다.", "균역법을 실시하였다.", "속대전을 편찬하였다."], "경국대전 반포=성종, 집현전=세종, 균역법·속대전=영조."),
("한국사", 3, "조선 영조의 정책으로 옳은 것은?", ["균역법을 실시하여 군포를 1필로 줄였다.", "규장각을 설치하였다.", "장용영을 설치하였다.", "수원 화성을 건설하였다.", "대동법을 처음 경기도에 실시하였다."], "규장각·장용영·화성=정조, 대동법(경기)=광해군."),
("한국사", 4, "임진왜란 중의 사실로 옳지 않은 것은?", ["강홍립의 부대가 사르후 전투에 참전하였다.", "이순신이 한산도 대첩에서 승리하였다.", "김시민이 진주성에서 승리하였다.", "권율이 행주산성에서 승리하였다.", "훈련도감이 설치되었다."], "사르후 전투(1619)는 광해군 때 명-후금 전쟁."),
("한국사", 3, "병자호란에 대한 설명으로 옳은 것은?", ["인조가 남한산성으로 피신하였다가 삼전도에서 항복하였다.", "광해군의 중립 외교로 일어났다.", "정봉수가 용골산성에서 항전하였다.", "강화도 조약이 체결되었다.", "의병장 곽재우가 활약하였다."], "정봉수=정묘호란, 곽재우=임진왜란."),
("한국사", 3, "실학자와 주장의 연결로 옳은 것은?", ["유형원 – 균전론", "박지원 – 여전론", "정약용 – 한전론", "이익 – 수레와 선박의 이용", "박제가 – 정전제만 주장"], "이익=한전론, 정약용=여전론·정전론, 박지원·박제가=상공업 진흥, 수레·선박."),
("한국사", 4, "다음 내용이 포함된 조약은?\n\"조선국은 자주국으로서 일본국과 평등한 권리를 보유한다.\" \"부산 외 2개 항구를 개항한다.\"", ["강화도 조약(조일 수호 조규)", "조미 수호 통상 조약", "제물포 조약", "한성 조약", "을사늑약"], "1876 강화도 조약: 청의 종주권 부인 의도, 3개 항구 개항, 해안 측량권, 치외 법권."),
("한국사", 3, "갑오개혁의 내용으로 옳은 것은?", ["과거제 폐지와 신분제 철폐", "지계 발급", "원수부 설치", "대한국 국제 반포", "광무 연호 사용"], "②~⑤는 대한제국 광무개혁."),
("한국사", 4, "독립 협회의 활동으로 옳은 것은?", ["관민 공동회를 열고 헌의 6조를 결의하였다.", "대한민국 임시 정부를 수립하였다.", "105인 사건으로 해체되었다.", "물산 장려 운동을 주도하였다.", "조선 혁명 선언을 발표하였다."], "105인 사건=신민회, 조선 혁명 선언=의열단(신채호)."),
("한국사", 3, "1910년대 일제의 식민 통치 방식은?", ["헌병 경찰을 통한 무단 통치", "문화 통치와 보통 경찰제", "민족 말살 통치와 황국 신민화", "산미 증식 계획", "국가 총동원법"], "1910년대 무단 통치(토지 조사 사업, 회사령), 1920년대 문화 통치(산미 증식 계획), 1930년대 후반 민족 말살 통치."),
("한국사", 3, "3·1 운동의 영향으로 옳은 것은?", ["대한민국 임시 정부 수립의 계기가 되었다.", "갑신정변이 일어났다.", "국채 보상 운동이 시작되었다.", "을사늑약이 체결되었다.", "신간회가 해체되었다."], "3·1 운동(1919) → 임시 정부 수립, 일제 통치 방식 변화(문화 통치)."),
("한국사", 4, "다음 사건을 순서대로 나열한 것은?\n(가) 5·18 민주화 운동  (나) 4·19 혁명  (다) 6월 민주 항쟁  (라) 유신 헌법 제정", ["(나)-(라)-(가)-(다)", "(나)-(가)-(라)-(다)", "(라)-(나)-(가)-(다)", "(나)-(라)-(다)-(가)", "(라)-(가)-(나)-(다)"], "4·19(1960) → 유신 헌법(1972) → 5·18(1980) → 6월 항쟁(1987)."),
("한국사", 3, "6월 민주 항쟁의 결과로 옳은 것은?", ["대통령 직선제 개헌이 이루어졌다.", "유신 헌법이 제정되었다.", "이승만 정부가 무너졌다.", "5·16 군사 정변이 일어났다.", "제헌 국회가 구성되었다."], "1987년 6·29 선언 → 5년 단임 대통령 직선제."),
]
